/**
 * The TPC-BiH benchmark (Kaufmann et al., "TPC-BiH: A Benchmark for Bitemporal Databases", TPCTC 2013): the finder route of
 * each case. A case's expected rows are those the report's SQL returns on the generated data; a case no finder query can ask
 * as the report does is skipped with the reason, so the gap stays visible. The cases are generated by
 * scripts/generate_tpch_bih_specs.py from the Python project's tpch_bih_specs. Each case also runs as the report's SQL.
 */
import { describe, it, beforeAll, afterAll } from 'vitest';
import { DuckDBInstance, DuckDBConnection } from '@duckdb/node-api';
import { registerDuckDb, DuckDbRunner } from './duckdb-runner';
import { expectRows, projectRows, runExpectation } from './spec-harness';
import { seedTpchBih } from './tpch-bih-data';
import { tpchBihFinders } from './tpch-bih-finders';
import { TPCH_BIH_SPECS, TPCH_BIH_SQL_CASES } from './specs/cases/tpch-bih';

let instance: DuckDBInstance;
let conn: DuckDBConnection;
let runner: DuckDbRunner;

beforeAll(async () => {
  instance = await DuckDBInstance.create(':memory:');
  conn = await instance.connect();
  runner = registerDuckDb(conn);
  await seedTpchBih(conn);
}, 120_000);

afterAll(() => {
  conn.disconnectSync();
  instance.closeSync();
});

describe('TPC-BiH', () => {
  const q = tpchBihFinders();
  for (const c of TPCH_BIH_SPECS) {
    it.skipIf(c.expected.skip !== undefined)(c.name, () => runExpectation(c.query(q), runner, c.expected));
  }
});

// The report's SQL, translated for DuckDB, returns the expected rows: the case is as the report asks it (Python's test_tpch_bih_sql).
// Every case runs here, including those no finder query can ask.
describe('TPC-BiH, as the report\'s SQL', () => {
  // the tables that are not versioned (region, nation) are not qualified by the translation
  beforeAll(async () => { await conn.run("SET schema = 'tpch'"); });
  for (const c of TPCH_BIH_SQL_CASES) {
    it(c.id, async () => {
      const statements = [...c.statements];
      const query = statements.pop()!;
      for (const statement of statements) await conn.run(statement);
      const result = await conn.run(query);
      const rows: unknown[][] = [];
      for (let i = 0; i < result.chunkCount; i++) rows.push(...result.getChunk(i).getRows());
      expectRows(projectRows(c, result.columnNames(), rows), c.rows, c.approximate);
    });
  }
});
